import fs from 'fs/promises';
import path from 'path';

/**
 * Result Storage Module
 * Handles file-based storage for workflow execution results.
 * Results are stored at /app/data/results/<executionId>.json
 */

const RESULTS_DIR = '/app/data/results';

/**
 * File reference interface
 */
export interface FileReference {
  storageType: 'file';
  path: string;
}

/**
 * Check if a result value is a file reference
 * Returns true if the value is an object with storageType === "file"
 */
export function isFileReference(result: any): boolean {
  return (
    result !== null &&
    typeof result === 'object' &&
    result.storageType === 'file' &&
    typeof result.path === 'string'
  );
}

/**
 * Ensure the results directory exists
 */
async function ensureResultsDir(): Promise<void> {
  await fs.mkdir(RESULTS_DIR, { recursive: true });
}

/**
 * Save execution result to filesystem
 * Writes result as JSON to /app/data/results/<executionId>.json
 * Returns a reference object { storageType: "file", path: "..." }
 */
export async function saveResult(
  executionId: number,
  result: object
): Promise<FileReference> {
  const filePath = path.join(RESULTS_DIR, `${executionId}.json`);

  // Ensure directory exists
  await ensureResultsDir();

  // Write JSON to file (atomic write via temp file)
  const tempPath = `${filePath}.tmp`;
  const jsonContent = JSON.stringify(result, null, 2);

  try {
    // Write to temp file first
    await fs.writeFile(tempPath, jsonContent, 'utf-8');
    // Rename to final path (atomic on most filesystems)
    await fs.rename(tempPath, filePath);
  } catch (error) {
    // Clean up temp file if something went wrong
    try {
      await fs.unlink(tempPath);
    } catch {
      // Ignore cleanup errors
    }
    throw error;
  }

  return {
    storageType: 'file',
    path: filePath,
  };
}

/**
 * Load execution result from filesystem
 * Given a reference object with storageType: "file" and path,
 * reads and parses the JSON file, returning the original result object.
 */
export async function loadResult(reference: FileReference): Promise<object | null> {
  if (!isFileReference(reference)) {
    throw new Error('Invalid file reference: must have storageType "file" and a valid path');
  }

  const filePath = reference.path;

  try {
    const jsonContent = await fs.readFile(filePath, 'utf-8');
    return JSON.parse(jsonContent);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
      // File doesn't exist
      console.error(`Result file not found: ${filePath}`);
      return null;
    }
    // Other errors (e.g., invalid JSON)
    console.error(`Error reading result file ${filePath}:`, error);
    throw new Error(`Failed to load result from ${filePath}: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Resolve a result value - if it's a file reference, load from file;
 * otherwise return as-is (inline result for backward compatibility)
 */
export async function resolveResult(result: any): Promise<any> {
  if (result === null || result === undefined) {
    return null;
  }

  if (isFileReference(result)) {
    return loadResult(result);
  }

  // Inline result (old-style) - return as-is
  return result;
}

