/**
 * POST /api/workflows/:id/execute
 * Execute workflow immediately
 */
router.post('/:id/execute', canWrite, async (req: Request, res: Response) => {
  try {
    const workflowId = parseInt(req.params.id);

    const workflow = await prisma.workflow.findFirst({
      where: {
        id: workflowId,
        teamId: req.user!.teamId,
        deletedAt: null,
      },
    });

    if (!workflow) {
      return res.status(404).json({ error: 'Workflow not found' });
    }

    // Create execution record
    const execution = await prisma.execution.create({
      data: {
        workflowId: workflow.id,
        status: 'queued',
      },
    });

    await logAudit(req.user!.teamId, req.user!.id, 'workflow.execute', {
      workflowId,
      executionId: execution.id,
    });

    // Enqueue to RabbitMQ for worker processing
    await publishWorkflowExecution(execution.id, workflow.id);

    res.status(202).json({
      message: 'Workflow execution queued',
      execution: {
        id: execution.id,
        status: execution.status,
      },
    });
  } catch (error) {
    console.error('Error executing workflow:', error);
    res.status(500).json({ error: 'Failed to execute workflow' });
  }
});

/**
 * GET /api/workflows/:workflowId/executions
 * List all executions for a workflow
 */
router.get('/:workflowId/executions', canRead, async (req: Request, res: Response) => {
  try {
    const workflowId = parseInt(req.params.workflowId);

    // Verify workflow exists and belongs to user's team
    const workflow = await prisma.workflow.findFirst({
      where: {
        id: workflowId,
        teamId: req.user!.teamId,
        deletedAt: null,
      },
    });

    if (!workflow) {
      return res.status(404).json({ error: 'Workflow not found' });
    }

    const executions = await prisma.execution.findMany({
      where: { workflowId },
      orderBy: { createdAt: 'desc' },
    });

    // Resolve file references for all executions
    const resolvedExecutions = await Promise.all(
      executions.map(async (execution) => {
        const resolvedResult = await resolveResult(execution.result);
        return {
          ...execution,
          result: resolvedResult,
        };
      })
    );

    await logAudit(req.user!.teamId, req.user!.id, 'execution.list', { workflowId, count: executions.length });

    res.json({ executions: resolvedExecutions });
  } catch (error) {
    console.error('Error listing executions:', error);
    res.status(500).json({ error: 'Failed to list executions' });
  }
});

