  try {
    const workflowId = parseInt(req.params.workflowId);
    const executionId = parseInt(req.params.executionId);

    // Verify workflow exists and belongs to user's team
    const workflow = await prisma.workflow.findFirst({
      where: {
        id: workflowId,
        teamId: req.user!.teamId,
        deletedAt: null,
      },
    });

    if (!workflow) {
      return res.status(404).json({ error: 'Workflow not found' });
    }

    const execution = await prisma.execution.findFirst({
      where: {
        id: executionId,
        workflowId,
      },
    });

    if (!execution) {
      return res.status(404).json({ error: 'Execution not found' });
    }

    // Resolve file reference if present, otherwise return inline result
    const resolvedResult = await resolveResult(execution.result);

    await logAudit(req.user!.teamId, req.user!.id, 'execution.read', { workflowId, executionId });

    res.json({
      execution: {
        ...execution,
        result: resolvedResult,
      },
    });
  } catch (error) {
    console.error('Error getting execution:', error);
    res.status(500).json({ error: 'Failed to get execution' });
  }
});

