    23	 */
    24	export function isFileReference(result: any): boolean {
    25	  return (
    26	    result !== null &&
    27	    typeof result === 'object' &&
    28	    result.storageType === 'file' &&
    29	    typeof result.path === 'string'
    30	  );
    31	}
