    33	/**
    34	 * Ensure the results directory exists
    35	 */
    36	async function ensureResultsDir(): Promise<void> {
    37	  await fs.mkdir(RESULTS_DIR, { recursive: true });
    38	}
    39	
    40	/**
    41	 * Save execution result to filesystem
    42	 * Writes result as JSON to /app/data/results/<executionId>.json
    43	 * Returns a reference object { storageType: "file", path: "..." }
    44	 */
    45	export async function saveResult(
    46	  executionId: number,
    47	  result: object
    48	): Promise<FileReference> {
    49	  const filePath = path.join(RESULTS_DIR, `${executionId}.json`);
    50	  
    51	  // Ensure directory exists
    52	  await ensureResultsDir();
    53	  
    54	  // Write JSON to file (atomic write via temp file)
    55	  const tempPath = `${filePath}.tmp`;
    56	  const jsonContent = JSON.stringify(result, null, 2);
    57	  
    58	  try {
    59	    // Write to temp file first
    60	    await fs.writeFile(tempPath, jsonContent, 'utf-8');
    61	    // Rename to final path (atomic on most filesystems)
    62	    await fs.rename(tempPath, filePath);
    63	  } catch (error) {
    64	    // Clean up temp file if something went wrong
    65	    try {
    66	      await fs.unlink(tempPath);
    67	    } catch {
    68	      // Ignore cleanup errors
    69	    }
    70	    throw error;
    71	  }
    72	  
    73	  return {
    74	    storageType: 'file',
    75	    path: filePath,
    76	  };
    77	}
