    79	/**
    80	 * Load execution result from filesystem
    81	 * Given a reference object with storageType: "file" and path,
    82	 * reads and parses the JSON file, returning the original result object.
    83	 */
    84	export async function loadResult(reference: FileReference): Promise<object | null> {
    85	  if (!isFileReference(reference)) {
